import grpc
from concurrent import futures
import jinja2
import logging
import os

import report_pb2
import report_pb2_grpc

logger = logging.getLogger(__name__)

class ReportServicer(report_pb2_grpc.ReportServiceServicer):
    """gRPC service that generates formatted reports from templates."""

    def __init__(self):
        self.template_cache = {}
        self.env = jinja2.Environment(
            loader=jinja2.BaseLoader(),
            autoescape=False
        )

    def GenerateReport(self, request, context):
        """Generate a report using user-provided template string."""
        try:
            template_str = request.template_body
            report_data = {
                'title': request.title,
                'author': request.author,
                'sections': list(request.sections),
                'metadata': dict(request.metadata),
                'generated_at': self._get_timestamp()
            }

            # Render the user-supplied template with report data
            template = self.env.from_string(template_str)
            rendered = template.render(**report_data)

            return report_pb2.ReportResponse(
                status=report_pb2.SUCCESS,
                rendered_content=rendered,
                byte_count=len(rendered.encode('utf-8'))
            )
        except jinja2.TemplateSyntaxError as e:
            context.set_code(grpc.StatusCode.INVALID_ARGUMENT)
            context.set_details(f'Template syntax error: {e.message}')
            return report_pb2.ReportResponse(status=report_pb2.TEMPLATE_ERROR)
        except Exception as e:
            logger.error(f'Report generation failed: {e}')
            context.set_code(grpc.StatusCode.INTERNAL)
            context.set_details('Internal rendering error')
            return report_pb2.ReportResponse(status=report_pb2.INTERNAL_ERROR)

    def _get_timestamp(self):
        from datetime import datetime
        return datetime.utcnow().isoformat()

    def ValidateTemplate(self, request, context):
        """Validate a template without rendering it."""
        try:
            self.env.parse(request.template_body)
            return report_pb2.ValidationResponse(valid=True, message='OK')
        except jinja2.TemplateSyntaxError as e:
            return report_pb2.ValidationResponse(
                valid=False, 
                message=f'Line {e.lineno}: {e.message}'
            )


def serve():
    server = grpc.server(futures.ThreadPoolExecutor(max_workers=10))
    report_pb2_grpc.add_ReportServiceServicer_to_server(
        ReportServicer(), server
    )

    port = os.environ.get('GRPC_PORT', '50051')
    server.add_insecure_port(f'[::]:{port}')

    logger.info(f'Report service starting on port {port}')
    server.start()
    server.wait_for_termination()


if __name__ == '__main__':
    logging.basicConfig(level=logging.INFO)
    serve()
